contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: from is an address to act as sender (must be this contract since only this contract deployed c can be msg.sender for calls), to is recipient, amount is transfer amount
    function run(address to, uint256 amount) public payable {
        require(true);
        // Preconditions: this test contract is the owner/initial holder because checker deploys fresh C with msg.sender = this contract.
        // Read before-values
        address from = address(this);
        uint256 beforeFromBalance = c.balanceOf(from); if (__ESBMC_reverted()) return;
        uint256 beforeToBalance = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 beforeTotal = c.totalSupply(); if (__ESBMC_reverted()) return;

        // Execute transfer and catch revert
        bool reverted;
        c.transfer(to, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read after-values
        uint256 afterFromBalance = c.balanceOf(from); if (__ESBMC_reverted()) return;
        uint256 afterToBalance = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 afterTotal = c.totalSupply(); if (__ESBMC_reverted()) return;

        // If transfer succeeded (did not revert), then totalSupply must be unchanged
        // and balances of from+to must equal their previous sum (i.e., transfer is just movement between them).
        assert(reverted || (afterTotal == beforeTotal && afterFromBalance + afterToBalance == beforeFromBalance + beforeToBalance));
    }

    receive() external payable { }
}

